const raw = $json.content?.parts?.[0]?.text;

if (!raw) {
  throw new Error('AI returned no qualification data');
}

let result;

try {
  const clean = String(raw).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  result = JSON.parse(clean);
} catch (error) {
  throw new Error('Invalid AI JSON: ' + error.message);
}

const score = result.lead_score;

if (!Number.isInteger(score) || score < 0 || score > 100) {
  throw new Error('Invalid lead score');
}

if (
  typeof result.ai_summary !== 'string' ||
  !result.ai_summary.trim()
) {
  throw new Error('Missing AI summary');
}

const original = $('LeadInput').first().json;

return {
  json: {
    ...original,
    lead_score: score,
    ai_summary: result.ai_summary,
    lead_priority: score >= 70
      ? 'high'
      : score >= 40
        ? 'medium'
        : 'low',
    qualification: {
      reasoning: result.reasoning ?? '',
      suggested_next_action: result.suggested_next_action ?? ''
    }
  }
};

const raw = $json.text ?? $json.output;

if (typeof raw !== 'string' || !raw.trim()) {
  throw new Error('Groq returned no text');
}

let result;

try {
  const clean = raw.trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/, '');

  result = JSON.parse(clean);
} catch {
  throw new Error('Invalid Groq JSON');
}

const score = result.lead_score;

if (!Number.isInteger(score) || score < 0 || score > 100) {
  throw new Error('Invalid Groq score');
}

for (const key of [
  'ai_summary',
  'reasoning',
  'suggested_next_action'
]) {
  if (typeof result[key] !== 'string') {
    throw new Error(`Invalid field: ${key}`);
  }
}

if (!result.ai_summary.trim()) {
  throw new Error('Empty AI summary');
}

const original = $('LeadInput').first().json;

return {
  json: {
    ...original,
    lead_score: score,
    ai_summary: result.ai_summary,
    lead_priority: score >= 70
      ? 'high'
      : score >= 40 ? 'medium' : 'low',
    qualification: {
      reasoning: result.reasoning,
      suggested_next_action: result.suggested_next_action
    }
  }
};
